  "help.chitInstallments": "अधिकांश बड़ी चिट्स समान मासिक शेयर (मूल्य ÷ महीने) का उपयोग करती हैं। कुछ समूह घटती किश्तों का उपयोग करते हैं (उच्च जल्दी, बाद में कम)। वह प्रकार चुनें जो आपके समूह से मेल खाता हो।",
