  "help.chitDiscount": "नीलामी में आप पूर्ण चिट मूल्य से कम स्वीकार करते हैं — यह छूट अन्य सदस्यों के साथ साझा की जाती है। आपको कभी भी पूरी चिट राशि नकद नहीं मिलती।",
  "help.chitAdvisor": "उन महीनों की तुलना करें जब आप चिट ले सकते हैं: अनुमानित छूट, फोरमैन के बाद भुगतान, उस महीने आपके अन्य बिल और अधिकतम नुकसान जिसे आप स्वीकार करने के लिए तैयार हैं।",
  "help.chitMaxLoss": "हम आपकी आय, मासिक बकाया राशि, खुले ऋण, अतिदेय बिल और बचत से अधिकतम नुकसान का सुझाव देते हैं — एक निश्चित % नहीं। जल्दी लेना अक्सर इससे अधिक होता है; बाद के महीनों में आमतौर पर कम खर्च होता है।",
  "help.loanExtraTiming": "आने वाले महीनों को दिखाता है: जब अन्य बिल हल्के होते हैं ताकि आप इस ऋण पर अतिरिक्त भुगतान कर सकें, और भारी महीने जब आपको न्यूनतम पर रहना चाहिए।",
  "help.incomeEntryBasis": "टेक - होम उन चीज़ों से मेल खाता है, जो टैक्स के बाद आपके बैंक में आती हैं, __ CT0 __, और निश्चित कटौती — दबाव और मुफ्त - नकद गणित के लिए सबसे अच्छा। सकल तभी उपयोगी है जब आपके द्वारा दर्ज किया गया हर नंबर पूर्व - कर हो; अगर घर से होने वाली आय सकल आय से कम है, तो मुफ्त नकद आपके वास्तविक बैंक बैलेंस से कम दिखाई दे सकता है।",
