  "profileHub.scoreFix.payFirstHint": "अतिदेय/उच्च-ब्याज भार को सबसे तेजी से साफ़ करता है।",
  "profileHub.scoreWhy.pressure.what": "यह मापता है कि आपकी आय का कितना हिस्सा बिलों और अतिदेय वस्तुओं में बंद है।",
