  "profileHub.scoreWhy.pressure.mid": "आय का एक उल्लेखनीय हिस्सा आवर्ती देय राशि में चला जाता है।",
  "profileHub.scoreWhy.pressure.low": "अभी आय के सापेक्ष बिलों का प्रबंधन संभव है।",
  "profileHub.scoreWhy.health.what": "बिल का बोझ, भुगतान की आदतें, बचत बफर और ऋण की प्रवृत्ति को जोड़ती है।",
  "profileHub.scoreWhy.health.low": "बोझ, बफर या भुगतान स्थिरता में कमजोरी इसे नीचे खींच रही है।",
  "profileHub.scoreWhy.health.mid": "कुछ क्षेत्रों में ठोस - कुछ आदतें या बफ़र्स इसे उठा सकते हैं।",
  "profileHub.scoreWhy.health.good": "कुल मिलाकर आदतें और बफ़र्स स्वस्थ दिखते हैं।",
  "profileHub.scoreWhy.runway.what": "यदि आय रुकी हुई है (तरल बचत + मुफ्त नकदी) तो आप ऐसे महीनों में आवश्यक चीजें कवर कर सकते हैं।",
  "profileHub.scoreWhy.runway.critical": "बहुत पतली गद्दी - आय के एक झटके को सहना मुश्किल होगा।",
  "profileHub.scoreWhy.runway.thin": "3-6 महीने के आरामदायक रिज़र्व के नीचे।",
  "profileHub.scoreWhy.runway.ok": "रनवे फिलहाल सुरक्षित दायरे में है।",
  "profileHub.scoreWhy.flexibility.what": "निश्चित मासिक बकाया के बाद आपके पास कितनी जगह है।",
  "profileHub.scoreWhy.flexibility.low": "अधिकांश आय पहले से ही आवर्ती बिलों के लिए प्रतिबद्ध है।",
  "profileHub.scoreWhy.flexibility.ok": "आप हर महीने सार्थक मुफ़्त नकदी बरकरार रखते हैं।",
  "profileHub.scoreWhy.debt.what": "EMI और मासिक आय के हिस्से के रूप में ऋण भुगतान।",
  "profileHub.scoreWhy.debt.high": "EMI भार भारी है - नए ऋण नकदी प्रवाह पर दबाव डालेंगे।",
  "profileHub.scoreWhy.debt.ok": "ऋण भुगतान एक प्रबंधनीय दायरे में है।",
  "profileHub.scoreWhy.lending.what": "आपके द्वारा उधार दिए गए या प्राप्त किए गए समय पर पुनर्भुगतान को ट्रैक करता है।",
  "profileHub.scoreWhy.lending.empty": "अभी तक कोई उधार प्रविष्टियाँ नहीं - इस स्कोर को बनाने के लिए सौदे जोड़ें और पुनर्भुगतान लॉग करें।",
  "profileHub.scoreWhy.lending.low": "देर से या आंशिक भुगतान से भरोसा कम हुआ।",
  "profileHub.scoreWhy.lending.ok": "चुकौती इतिहास विश्वसनीय लगता है.",
  "profileHub.scoreFix.pressure.clearOverdue": "पहले अतिदेय बिलों का निपटान करें - वे इस स्कोर को सबसे अधिक नुकसान पहुंचाते हैं।",
  "profileHub.scoreFix.pressure.trimSubscriptions": "सदस्यताओं और वैकल्पिक EMIs की समीक्षा करें जिन्हें आप रोक सकते हैं।",
  "profileHub.scoreFix.pressure.payOnTime": "दबाव को स्थिर करने के लिए इस महीने देय तिथियों से पहले भुगतान करें।",
  "profileHub.scoreFix.runway.buildReserve": "प्रत्येक वेतन दिवस पर एक निश्चित राशि को तरल बचत में स्थानांतरित करें।",
  "profileHub.scoreFix.runway.reduceBurn": "रनवे का विस्तार करने के लिए गैर-आवश्यक आवर्ती बिलों में कटौती करें।",
  "profileHub.scoreFix.health.reduceBurden": "अधिक बोझ वाली प्रतिबद्धताओं को कम करें या पुनर्निर्धारित करें।",
  "profileHub.scoreFix.health.buildBuffer": "तरल बचत में 3-6 महीने के खर्च का लक्ष्य रखें।",
  "profileHub.scoreFix.health.payOnTime": "भुगतान क्रम बनाए रखें - प्रत्येक बिल भुगतान को लॉग करें।",
  "profileHub.scoreFix.health.reduceDebt": "सबसे पहले उच्चतम-ब्याज शेष को हटा दें।",
  "profileHub.scoreFix.health.keepGoing": "Keep current habits — you're on track.",
  "profileHub.scoreFix.health.general": "आय, बिल और बचत लॉग करें ताकि स्कोर सटीक रहे।",
  "profileHub.scoreFix.flexibility.reduceBurden": "आवर्ती देय राशि कम करें या जहां संभव हो EMI पर बातचीत करें।",
  "profileHub.scoreFix.flexibility.trackSpend": "परिवर्तनीय खर्च लॉग करें ताकि मुफ़्त नकद वास्तविकता से मेल खाए।",
  "profileHub.scoreFix.debt.attackHighInterest": "भुगतान क्रम में क्रेडिट कार्ड और उच्च दर वाले ऋण को प्राथमिकता दें।",
