  "wealthDetail.property.holdGoodDetail": "खरीदारी के बाद से हुई वृद्धि ने मुद्रास्फीति और विशिष्ट शहरी मानकों को पीछे छोड़ दिया है। जब तक आपको तरलता की आवश्यकता न हो, होल्ड करने पर विचार करें।",
