  "wealthDetail.property.holdNeutral": "होल्ड सलाह के लिए खरीद वर्ष और कीमत जोड़ें",
  "wealthDetail.property.holdNeutralDetail": "यह दर्ज करें कि आपने कब खरीदारी की और किस कीमत पर सीएजीआर अनलॉक करना है, मुद्रास्फीति-समायोजित रिटर्न और मार्गदर्शन प्राप्त करना है।",
  "wealthDetail.property.holdModerate": "धारण करने योग्य - मामूली वास्तविक लाभ",
  "wealthDetail.property.holdModerateDetail": "नाममात्र वृद्धि चक्रवृद्धि आधार पर मुद्रास्फीति को मात देती है, लेकिन वास्तविक रिटर्न मध्यम होता है। यदि आपको तरलता की आवश्यकता नहीं है तो रुकें; बिक्री केवल एक मजबूत पुनर्निवेश योजना या जीवन-घटना नकदी की आवश्यकता के लिए ही समझ में आती है।",
  "wealthDetail.property.holdMature": "परिपक्व पकड़ - धन भंडार, त्वरित नकदी नहीं",
  "wealthDetail.property.holdMatureDetail": "You have held long enough to ride multiple cycles. Real returns are positive but modest — this asset works as generational wealth and inflation hedge. Avoid selling unless relocation, debt payoff, or diversification clearly wins after tax and brokerage.",
  "wealthDetail.property.realReturnNote": "Assumes ~{inflation}% annual inflation (India long-run average).",
