  "wealthDetail.property.yearsToTarget": "मौजूदा गति से, 12% सीएजीआर लक्ष्य तक पहुंचने में ~{years} वर्ष और लगेंगे।",
  "wealthDetail.property.outlookMetro": "Metro corridors: infra (metro lines, IT parks) often lifts land values — watch local RERA/project news.",
  "wealthDetail.property.outlookTier2": "Tier-2 cities: industrial corridors and highway links can accelerate appreciation in 5–8 year cycles.",
  "wealthDetail.property.outlookTier3": "Smaller towns: liquidity is lower — favour long holds and verify title before major price revisions.",
  "wealthDetail.property.outlookAreaFallback": "आपका इलाका",
  "wealthDetail.property.purchaseThen": "Purchase price (then)",
  "wealthDetail.property.inflationCostToday": "मुद्रास्फीति-समायोजित लागत (आज)",
  "wealthDetail.property.inflationCostHint": "आपका वर्तमान मूल्य नहीं - आज के रुपये में मूल खरीदारी का मूल्य क्या है।",
  "wealthDetail.property.narrative.inflationAdjustedCost": "Your ₹{purchase} purchase equals roughly ₹{todayEquivalent} in today's money after {years} years at ~{inflation}% compounded inflation — real growth is measured against that, not the original price alone.",
  "wealthDetail.property.narrative.purchaseDerived": "खरीद मूल्य आपके द्वारा दर्ज दर × क्षेत्र से आता है - यदि कुल गलत लगता है तो संपादित करें पर टैप करें।",
  "wealthDetail.property.narrative.realReturnExplain": "Nominal CAGR {cagr}% minus ~{inflation}% inflation ≈ {real}% real return per year — property often looks strong in rupee terms while barely beating inflation after costs.",
  "wealthDetail.property.narrative.vsBenchmarkExplain": "Your {cagr}% CAGR vs ~{benchmark}% typical for this city tier ({delta}% difference) — use as a rough peer check, not a buy/sell signal.",
  "wealthDetail.property.narrative.longHoldLiquidity": "लंबे समय तक रखने से समय का जोखिम कम हो जाता है लेकिन पूंजी लॉक हो जाती है - इसे बेचने योग्य संपत्ति मानने से पहले 6-12 महीने के खर्चों को कहीं और तरल रखें।",
  "wealthDetail.property.narrative.rentYieldExplain": "Estimated gross rent yield ~{yield}% — compare with FD/PPF after tax; if you live in the property, treat rent savings as implicit yield.",
  "wealthDetail.property.narrative.rentVsIncome": "यदि पूरी तरह से किराए पर लिया गया है, तो सकल किराया आपकी घोषित मासिक आय का ~{pct}% होगा - जांचें कि क्या यह आपके वास्तविक या प्राप्त करने योग्य किराए से मेल खाता है।",
  "wealthDetail.property.narrative.valueVsIncome": "यह संपत्ति कागज पर आपकी वार्षिक आय ~{multiple}× है - एक बड़ा संकेंद्रण; इसे आपातकालीन और विविधीकरण योजना में शामिल करें।",
  "wealthDetail.property.narrative.highValueTier3Liquidity": "एक छोटे शहर में इस मूल्य पर, खरीदार ढूंढने में कई महीने लग सकते हैं - कीमत वास्तविक रूप से और तत्काल उपलब्ध नकदी के रूप में पूर्ण मूल्य की गणना करने से बचें।",
  "wealthDetail.property.narrative.highValueTier2Liquidity": "टियर-2 बाज़ार के लिए उच्च टिकट - अपने बताए गए मूल्य पर त्वरित तरलता मानने से पहले हाल ही में पंजीकृत बिक्री को सत्यापित करें।",
  "wealthDetail.property.narrative.targetCagrReality": "यहां से 12% सीएजीआर का पीछा करने में आज की गति से ~{years} अधिक वर्ष लगेंगे - आपकी होल्डिंग ने पहले ही मजबूत नाममात्र लाभ दिया है; भविष्य के रिटर्न सामान्य हो सकते हैं।",
  "wealthDetail.property.narrative.landHold": "भूमि: सबसे कम रखरखाव लेकिन सबसे धीमी तरलता - 10+ वर्ष के क्षितिज के लिए सर्वोत्तम; लिस्टिंग से पहले बाधा, ज़ोनिंग और सड़क-चौड़ाई संबंधी अधिसूचनाओं की जाँच करें।",
  "wealthDetail.property.narrative.commercialHold": "वाणिज्यिक: रिक्ति और किरायेदार की गुणवत्ता स्थान के समान ही मायने रखती है - यदि फुटफॉल या पट्टे की शर्तें कमजोर होती हैं तो पुनर्मूल्यांकन करें।",
  "wealthDetail.property.narrative.residentialHold": "आवासीय: स्व-उपयोग से बेचने का दबाव कम हो जाता है; यदि किराए पर है, तो किरायेदार के टर्नओवर और सोसायटी के रखरखाव में बढ़ोतरी पर नज़र रखें।",
  "wealthDetail.property.narrative.verifyTitle": "किसी भी बिक्री से पहले: ऋणभार प्रमाणपत्र, संपत्ति कर रसीदें, और उत्परिवर्तन स्थिति - यहां देरी कागजी लाभ को मिटा देती है।",
